function card(p){let off=Math.round((p.mrp-p.price)/p.mrp*100),saved=wish.includes(p.id);return`<article class="store-card luxury-product-card"><div class="store-card-media"><div class="store-card-badges"><span class="badge">${p.badge}</span><span class="discount-badge">${off}% OFF</span></div><a href="product.html?id=${p.id}" aria-label="View ${p.name}"><img src="${p.image}" alt="${p.name}" loading="lazy"></a><button class="card-heart ${saved?"active":""}" data-wish="${p.id}" aria-label="${saved?"Remove from":"Add to"} wishlist">&#9825;</button><a class="card-quick" href="product.html?id=${p.id}">Quick View <span>&rarr;</span></a></div><div class="store-card-body"><small>${p.category}</small><h3><a href="product.html?id=${p.id}">${p.name}</a></h3><div class="card-rating"><span>&#9733;&#9733;&#9733;&#9733;&#9733;</span><small>${p.rating} &middot; ${34+p.id*7} reviews</small></div><div class="price"><b>${money(p.price)}</b><s>${money(p.mrp)}</s><em>Save ${money(p.mrp-p.price)}</em></div><div class="store-actions"><button class="btn primary" data-add="${p.id}" ${!p.stock?"disabled":""}>${p.stock?"Add to Bag":"Out of Stock"}</button><a class="btn card-detail" href="product.html?id=${p.id}" aria-label="View details for ${p.name}">View</a></div></div></article>`}
function syncStoreChrome(){const chrome=$(".store-chrome");if(!chrome)return;const height=Math.ceil(chrome.getBoundingClientRect().height||chrome.offsetHeight||180);document.documentElement.style.setProperty("--store-chrome-h",`${height}px`);
  /* Spacer stays at expanded height so compacting never shifts scrollY */
  if(!chrome.classList.contains("is-compact")){
    document.documentElement.style.setProperty("--store-chrome-spacer-h",`${height}px`);
  }
}
function bindStoreChromeScroll(){const chrome=$(".store-chrome");if(!chrome)return;if(!chrome.dataset.resizeBound&&"ResizeObserver" in window){chrome.dataset.resizeBound="1";new ResizeObserver(()=>syncStoreChrome()).observe(chrome)}if(chrome.dataset.scrollBound){syncStoreChrome();return}chrome.dataset.scrollBound="1";let ticking=false;const COMPACT_ON=72,COMPACT_OFF=12;const apply=()=>{const y=window.scrollY||window.pageYOffset||0;const isCompact=chrome.classList.contains("is-compact");let next=isCompact;if(!isCompact&&y>COMPACT_ON)next=true;else if(isCompact&&y<COMPACT_OFF)next=false;if(next!==isCompact)chrome.classList.toggle("is-compact",next);syncStoreChrome();ticking=false};const onScroll=()=>{if(ticking)return;ticking=true;requestAnimationFrame(apply)};window.addEventListener("scroll",onScroll,{passive:true});apply()}
function bind(){$$("[data-add]").forEach(b=>b.onclick=()=>add(+b.dataset.add));$$("[data-wish]").forEach(b=>b.onclick=()=>toggleWish(+b.dataset.wish));updateHeader();bindHeader();syncStoreChrome();bindStoreChromeScroll();enhanceAccountLoungeNav()}
function add(id,q=1){cart[id]=(cart[id]||0)+q;write("zivaraBag",cart);updateHeader();toast(P[id].name+" was added to your bag","success","Added to Bag")}
function toggleWish(id){wish=wish.includes(id)?wish.filter(x=>x!==id):[...wish,id];write("zivaraWishlist",wish);updateHeader();toast(wish.includes(id)?"This piece is saved for later.":"This piece was removed from your wishlist.",wish.includes(id)?"success":"info",wish.includes(id)?"Saved to Wishlist":"Wishlist Updated")}
