function checkoutField(name,label,type="text",icon="",full=false){let required=!label.includes("optional");return`<label class="luxury-field ${full?"full":""}"><span>${label}${required?"*":""}</span>${type==="textarea"?`<textarea name="${name}" aria-label="${label}"></textarea>`:`<input type="${type}" name="${name}" aria-label="${label}" ${required?"required":""}>`}<i aria-hidden="true">${icon==="mail"?"@":icon==="phone"?"&#9742;":icon==="pin"?"&#9670;":icon==="city"?"&#8962;":icon==="map"?"&#9670;":icon==="note"?"&#8801;":"&#9675;"}</i></label>`}
function luxuryCheckoutSummary(t){let items=Object.entries(cart).filter(([,q])=>q>0).map(([id,q])=>{let p=P[id];return`<div class="checkout-summary-item"><img src="${p.image}" alt="${p.name}"><div><small>${p.category}</small><b>${p.name}</b><span>Qty ${q}</span></div><strong>${money(p.price*q)}</strong></div>`}).join("");return`<aside class="checkout-summary"><div class="summary-heading"><div><p>YOUR ORDER</p><h2>Order summary</h2></div><a href="cart.html">Edit bag</a></div><div class="checkout-summary-items">${items}</div><details class="checkout-coupon"><summary>Have a private offer?<span>+</span></summary><div><input id="checkoutCoupon" placeholder="Enter offer code"><button type="button">Apply</button></div></details><label class="checkout-gift"><input type="checkbox"><span>&#10022;</span><div><b>Add luxury gift packaging</b><small>Signature box, ribbon and message card</small></div><strong>&#8377;149</strong></label><div class="checkout-totals"><p><span>Subtotal</span><b>${money(t.subtotal)}</b></p><p><span>Discount</span><b class="saving">&minus;${money(t.discount)}</b></p><p><span>Delivery</span><b>${t.shipping?money(t.shipping):"Complimentary"}</b></p><p><span>Estimated tax</span><b>Included</b></p><p class="grand"><span>Grand total<small>Inclusive of all taxes</small></span><b>${money(t.total)}</b></p>${t.discount?`<em>You save ${money(t.discount)} on this order</em>`:""}</div><div class="checkout-arrival"><span>&#9670;</span><div><b>Estimated arrival</b><small>${new Date(Date.now()+6*864e5).toLocaleDateString("en-IN",{day:"numeric",month:"long"})} &middot; Carefully packaged</small></div></div><div class="checkout-summary-trust"><span><b>100%</b>Authentic</span><span><b>Easy</b>Returns</span><span><b>Gift</b>Ready</span></div><blockquote>&ldquo;Beautiful packaging and service that feels genuinely personal.&rdquo;<small>&#9733;&#9733;&#9733;&#9733;&#9733; &middot; Verified Zivara customer</small></blockquote></aside>`}
function enhanceCheckoutAddressSelect(){let select=$('[name="addressType"]'),field=select?.closest(".luxury-field");if(!select||!field||field.classList.contains("address-select-ready"))return;field.classList.add("address-select-ready");select.hidden=true;field.insertAdjacentHTML("beforeend",`<button type="button" class="address-select-trigger" aria-haspopup="listbox" aria-expanded="false"><b>${select.value}</b><i aria-hidden="true"></i></button><div class="address-select-menu" role="listbox" aria-label="Address type">${[["Home","&#8962;","House or apartment"],["Work","&#9670;","Office or workplace"],["Other","&#9670;","Another delivery location"]].map((x,i)=>`<button type="button" role="option" tabindex="${i?"-1":"0"}" aria-selected="${String(select.value===x[0])}" data-address-type="${x[0]}"><span>${x[1]}</span><div><b>${x[0]}</b><small>${x[2]}</small></div><i>&#10003;</i></button>`).join("")}</div>`);let trigger=$(".address-select-trigger",field),menu=$(".address-select-menu",field),options=$$("[data-address-type]",field),close=()=>{field.classList.remove("open");trigger.setAttribute("aria-expanded","false")};trigger.onclick=()=>{let open=field.classList.toggle("open");trigger.setAttribute("aria-expanded",String(open));if(open)options.find(x=>x.getAttribute("aria-selected")==="true")?.focus()};options.forEach((option,index)=>{option.onclick=()=>{select.value=option.dataset.addressType;select.dispatchEvent(new Event("change",{bubbles:true}));trigger.querySelector("b").textContent=select.value;options.forEach(x=>{x.setAttribute("aria-selected",String(x===option));x.tabIndex=x===option?0:-1});close();trigger.focus()};option.onkeydown=e=>{if(["ArrowDown","ArrowUp"].includes(e.key)){e.preventDefault();options[(index+(e.key==="ArrowDown"?1:-1)+options.length)%options.length].focus()}if(e.key==="Escape"){close();trigger.focus()}}});document.addEventListener("click",e=>{if(!field.contains(e.target))close()})}
function field(name,label,type="text",full=false){return`<label class="field ${full?"full":""}"><span>${label}</span>${type==="textarea"?`<textarea name="${name}"></textarea>`:`<input type="${type}" name="${name}" ${label.includes("*")?"required":""}>`}<small class="error"></small></label>`}
