function luxuryWishlistAccountPage(){let rows=wish.map(id=>P[id]).filter(Boolean),orders=read("zivaraOrders",sampleOrders()),points=Math.max(500,orders.reduce((s,o)=>s+Math.round((o.total||0)/10),0));return`${header()}<main class="luxury-account lounge-subpage"><section class="account-hero lounge-compact-hero"><div class="store-shell"><div class="account-avatar"><span>PS</span><i>&#10022;</i></div><div class="account-welcome"><p>YOUR CURATED EDIT</p><h1>Saved pieces</h1><span>Everything you love, thoughtfully gathered in one beautiful place.</span></div><div class="account-hero-reward"><p>GOLD MEMBER</p><strong>${points.toLocaleString("en-IN")}</strong><span>Zivara reward points</span><i><b style="--progress:72%"></b></i><small>Your private benefits are active</small></div></div></section>${accountLoungeNavigation("wishlist")}<div class="lounge-page-shell store-shell"><section class="lounge-page-card lounge-wishlist"><header><div><p>YOUR WISHLIST</p><h2>Pieces worth remembering</h2></div><span>${rows.length} saved</span></header>${rows.length?`<div>${rows.map(p=>`<article><div class="lounge-wish-image"><a href="product.html?id=${p.id}"><img src="${p.image}" alt="${p.name}" loading="lazy"></a><span>${p.badge}</span><button type="button" data-wish="${p.id}" aria-label="Remove ${p.name} from wishlist">&times;</button></div><small>${p.category}</small><h3><a href="product.html?id=${p.id}">${p.name}</a></h3><div class="lounge-wish-rating"><span>&#9733;&#9733;&#9733;&#9733;&#9733;</span><small>${p.rating} &middot; ${34+p.id*7} reviews</small></div><p><b>${money(p.price)}</b><s>${money(p.mrp)}</s><em>Save ${money(p.mrp-p.price)}</em></p><div><button type="button" data-add="${p.id}">Add to bag</button><a href="product.html?id=${p.id}">View details</a></div></article>`).join("")}</div>`:`<div class="lounge-wishlist-empty"><i>&#9825;</i><h3>Your edit is waiting</h3><p>Save jewellery, beauty and accessories you would love to revisit.</p><a href="shop.html">Discover beautiful pieces &rarr;</a></div>`}</section><aside class="lounge-page-help"><p>PERSONAL SHOPPING</p><h2>Can&rsquo;t decide?</h2><span>Our concierge can help compare your saved pieces and recommend the perfect choice.</span><a href="https://wa.me/919999999999">Ask on WhatsApp</a><a href="shop.html">Continue discovering</a></aside></div><nav class="account-mobile-nav"><a href="account.html">&#9670;<span>Home</span></a><a href="orders.html">&#9633;<span>Orders</span></a><a class="active" href="wishlist.html">&#9825;<span>Saved</span></a><a href="profile.html">&#9675;<span>Profile</span></a></nav></main>${footer()}`}
function accountLoungeNavigation(active){const items=[["account","account.html","&#9670;","Dashboard"],["orders","orders.html","&#9633;","Orders"],["wishlist","wishlist.html","&#9825;","Wishlist"],["addresses","addresses.html","&#8962;","Addresses"],["rewards","account.html#accountRewards","&#10022;","Rewards"],["profile","profile.html","&#9675;","Profile"],["change-password","change-password.html","&#8984;","Settings"]];return`<nav class="account-lounge-nav store-shell" aria-label="Account navigation"><div class="account-lounge-track"><span class="account-lounge-thumb" aria-hidden="true"></span>${items.map(x=>`<a class="${active===x[0]?"active":""}" href="${x[1]}" data-lounge-tab="${x[0]}"><i aria-hidden="true">${x[2]}</i><span>${x[3]}</span></a>`).join("")}</div></nav>`}
function enhanceAccountLoungeNav(){const nav=$(".account-lounge-nav"),track=$(".account-lounge-track"),thumb=$(".account-lounge-thumb"),active=$(".account-lounge-nav a.active");if(!nav||!track||!thumb||!active||nav.dataset.loungeEnhanced==="1")return;nav.dataset.loungeEnhanced="1";const move=()=>{thumb.style.width=`${Math.max(active.offsetWidth,0)}px`;thumb.style.height=`${Math.max(active.offsetHeight,0)}px`;thumb.style.transform=`translate(${active.offsetLeft}px, ${active.offsetTop}px)`;thumb.classList.add("is-ready")};move();requestAnimationFrame(move);active.scrollIntoView({inline:"center",block:"nearest",behavior:"smooth"});window.addEventListener("resize",move,{passive:true});track.addEventListener("scroll",move,{passive:true})}
