if(key==="profile")content=`<form class="lounge-page-card lounge-form demo-form"><header><div><p>PERSONAL DETAILS</p><h2>My profile</h2></div><span>82% complete</span></header><div class="lounge-profile-intro"><div>PS<i>&#10022;</i></div><span><b>Priya Shah</b><small>Gold Member &middot; Since 2024</small></span><button type="button">Change photo</button></div><div class="lounge-form-grid">${checkoutField("first","First name","text","user")}${checkoutField("last","Last name","text","user")}${checkoutField("email","Email address","email","mail")}${checkoutField("phone","Mobile number","tel","phone")}<label class="luxury-field full"><span>Date of birth</span><input type="date" name="birthday"></label><label class="luxury-field full"><span>Preferred language</span><select name="language"><option>English</option><option>Hindi</option><option>Gujarati</option></select></label></div><div class="lounge-form-actions"><button type="submit">Save changes &rarr;</button><a href="account.html">Cancel</a></div></form>`;
